import { problemResponse } from "@github-app-token-broker/http/problem-details";
import { createOidcIdTokenAuthenticator } from "@github-app-token-broker/oidc/id-token-authenticator";
import type { SecretTextBinding } from "@github-app-token-broker/github/secrets";
import type { InstallationAccessTokenExchange } from "./installation-access-token-exchange.ts";
import { createInstallationAccessTokenExchange } from "./installation-access-token-exchange.ts";
import { parseSubjectTokenAudience } from "./subject-token-audience.ts";
import {
  handleTokenExchangeRequest,
  tokenExchangeMethodNotAllowedResponse,
} from "./token-exchange.ts";
import {
  assertTokenIssuancePolicyIssuersAreRegistered,
  type TokenIssuancePolicy,
} from "@github-app-token-broker/token-issuance-policy";
import {
  snapshotOidcProviderRegistrations,
  type OidcProviderRegistration,
} from "@github-app-token-broker/oidc/provider-registration";

export interface TokenExchangeComposition {
  readonly oidcProviderRegistrations: readonly OidcProviderRegistration[];
  readonly tokenIssuancePolicy: TokenIssuancePolicy;
}

export interface TokenExchangeWorkerRuntimeDependencies {
  readonly fetch: typeof fetch;
  readonly now: () => Date;
}

export interface TokenExchangeWorkerEnv {
  readonly GITHUB_API_BASE_URL?: string;
  readonly GITHUB_APP_ID: string;
  readonly GITHUB_APP_PRIVATE_KEY: SecretTextBinding;
  readonly TOKEN_BROKER_AUDIENCE: string;
  readonly TOKEN_EXCHANGE_RATE_LIMIT: {
    limit(options: { readonly key: string }): Promise<{ readonly success: boolean }>;
  };
}

export function createTokenExchangeWorker(
  composition: TokenExchangeComposition,
  runtimeDependencies: TokenExchangeWorkerRuntimeDependencies = {
    fetch: (input, init) => fetch(input, init),
    now: () => new Date(),
  },
): ExportedHandler<TokenExchangeWorkerEnv> {
  const oidcProviderRegistrations = snapshotOidcProviderRegistrations(
    composition.oidcProviderRegistrations,
  );
  const tokenIssuancePolicy = composition.tokenIssuancePolicy;
  assertTokenIssuancePolicyIssuersAreRegistered(tokenIssuancePolicy, oidcProviderRegistrations);
  const workerDependencies = Object.freeze({
    fetch: runtimeDependencies.fetch,
    now: runtimeDependencies.now,
    oidcProviderRegistrations,
    tokenIssuancePolicy,
  });
  let configuredRuntime:
    | {
        readonly audience: string;
        readonly tokenExchange: InstallationAccessTokenExchange;
      }
    | undefined;

  return {
    fetch(request, env) {
      const audience = parseSubjectTokenAudience(env.TOKEN_BROKER_AUDIENCE);
      configuredRuntime ??= {
        audience,
        tokenExchange: createInstallationAccessTokenExchange({
          githubAppDependencies: workerDependencies,
          oidcIdTokenAuthenticator: createOidcIdTokenAuthenticator(
            {
              providerRegistrations: workerDependencies.oidcProviderRegistrations,
              subjectTokenAudience: audience,
            },
            {
              fetch: (input, init) => workerDependencies.fetch(input, init),
              now: () => workerDependencies.now(),
              observe: (event) => console.warn(event),
            },
          ),
          tokenIssuancePolicy: workerDependencies.tokenIssuancePolicy,
        }),
      };

      if (configuredRuntime.audience !== audience) {
        throw new TypeError(
          "TOKEN_BROKER_AUDIENCE must not change during a Worker isolate lifetime",
        );
      }
      const tokenExchange = configuredRuntime.tokenExchange;

      const url = new URL(request.url);

      if (url.pathname !== "/token") {
        return problemResponse(404);
      }

      if (request.method !== "POST") {
        return tokenExchangeMethodNotAllowedResponse();
      }

      return handleTokenExchangeRequest(request, {
        exchange: (input) =>
          tokenExchange.exchange({
            ...input,
            githubApp: githubApp(env),
          }),
        now: () => workerDependencies.now(),
        rateLimit: async (key) => {
          const result = await env.TOKEN_EXCHANGE_RATE_LIMIT.limit({ key });

          return result.success;
        },
      });
    },
  };
}

function githubApp(env: TokenExchangeWorkerEnv) {
  return {
    ...(env.GITHUB_API_BASE_URL === undefined
      ? {}
      : { GITHUB_API_BASE_URL: env.GITHUB_API_BASE_URL }),
    GITHUB_APP_ID: env.GITHUB_APP_ID,
    GITHUB_APP_PRIVATE_KEY: env.GITHUB_APP_PRIVATE_KEY,
  };
}
import type { GitHubAppDependencies, GitHubAppEnv } from "@github-app-token-broker/github/app";
import type { OidcIdTokenAuthenticator } from "@github-app-token-broker/oidc/id-token-authenticator";
import type { TokenIssuancePolicy } from "@github-app-token-broker/token-issuance-policy";
import {
  type InstallationAccessTokenIssuanceFailureReason,
  issueInstallationAccessTokenForContext,
} from "./policy/installation-access-token-issuance.ts";
import { authenticateOidcIdToken, type OidcAuthenticationFailureReason } from "./authentication.ts";
import type { InstallationAccessTokenRequest } from "@github-app-token-broker/github/installation-access-token-request";

type TokenExchangeAuthorizationFailureReason = Extract<
  InstallationAccessTokenIssuanceFailureReason,
  "requested_permissions_unsupported" | "subject_token_unacceptable" | "target_unsupported"
>;
type TokenExchangeIssuanceFailureReason = Exclude<
  InstallationAccessTokenIssuanceFailureReason,
  TokenExchangeAuthorizationFailureReason
>;

export type InstallationAccessTokenExchangeResult =
  | { readonly expiresAt: string; readonly ok: true; readonly token: string }
  | {
      readonly ok: false;
      readonly reason: OidcAuthenticationFailureReason;
      readonly stage: "authentication";
    }
  | {
      readonly ok: false;
      readonly reason: TokenExchangeAuthorizationFailureReason;
      readonly stage: "authorization";
    }
  | {
      readonly ok: false;
      readonly reason: TokenExchangeIssuanceFailureReason;
      readonly stage: "issuance";
    };

export interface InstallationAccessTokenExchange {
  exchange(input: {
    readonly githubApp: GitHubAppEnv;
    readonly request: Request;
    readonly subjectToken: string;
    readonly tokenRequest: InstallationAccessTokenRequest;
  }): Promise<InstallationAccessTokenExchangeResult>;
}

export function createInstallationAccessTokenExchange({
  githubAppDependencies,
  oidcIdTokenAuthenticator,
  tokenIssuancePolicy,
}: {
  githubAppDependencies: GitHubAppDependencies;
  oidcIdTokenAuthenticator: OidcIdTokenAuthenticator;
  tokenIssuancePolicy: TokenIssuancePolicy;
}): InstallationAccessTokenExchange {
  return {
    async exchange({ githubApp, request, subjectToken, tokenRequest }) {
      const authentication = await authenticateOidcIdToken(
        subjectToken,
        request,
        oidcIdTokenAuthenticator,
      );

      if (!authentication.ok) {
        return {
          ok: false,
          reason: authentication.reason,
          stage: "authentication",
        };
      }

      const issuance = await issueInstallationAccessTokenForContext(
        githubApp,
        tokenIssuancePolicy,
        authentication.context,
        tokenRequest,
        githubAppDependencies,
      );

      if (issuance.ok) {
        return issuance;
      }

      if (isAuthorizationFailure(issuance.reason)) {
        return {
          ok: false,
          reason: issuance.reason,
          stage: "authorization",
        };
      }

      return {
        ok: false,
        reason: issuance.reason,
        stage: "issuance",
      };
    },
  };
}

function isAuthorizationFailure(
  reason: InstallationAccessTokenIssuanceFailureReason,
): reason is TokenExchangeAuthorizationFailureReason {
  return (
    reason === "requested_permissions_unsupported" ||
    reason === "subject_token_unacceptable" ||
    reason === "target_unsupported"
  );
}
import { jsonResponse } from "@github-app-token-broker/http/problem-details";
import { readRequestBodyUpTo } from "@github-app-token-broker/http/request-body";
import { normalizeInstallationAccessTokenRequest } from "@github-app-token-broker/github/installation-access-token-request";
import type { InstallationAccessTokenExchangeResult } from "./installation-access-token-exchange.ts";
import type { InstallationAccessTokenRequest } from "@github-app-token-broker/github/installation-access-token-request";
import type { InstallationAccessTokenIssuanceFailureReason } from "./policy/installation-access-token-issuance.ts";

const maxTokenExchangeBodyBytes = 64 * 1024;
const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const accessTokenType = "urn:ietf:params:oauth:token-type:access_token";
const legacyGithubInstallationAccessTokenType =
  "urn:chikachow:github-app-installation-access-token";
const oidcIdTokenType = "urn:ietf:params:oauth:token-type:id_token";
const unknownRateLimitKey = "unknown";
const unsupportedInvalidTargetParameters = ["audience"];
const unsupportedInvalidRequestParameters = [
  "actor_token",
  "actor_token_type",
  "authorization_details",
  "client_assertion",
  "client_assertion_type",
  "client_id",
  "client_secret",
];

export function tokenExchangeMethodNotAllowedResponse(): Response {
  return oauthErrorResponse(400, "invalid_request");
}

interface TokenExchangeEndpointRuntime {
  exchange(input: {
    readonly request: Request;
    readonly subjectToken: string;
    readonly tokenRequest: InstallationAccessTokenRequest;
  }): Promise<InstallationAccessTokenExchangeResult>;
  now(): Date;
  rateLimit(key: string): Promise<boolean>;
}

export async function handleTokenExchangeRequest(
  request: Request,
  runtime: TokenExchangeEndpointRuntime,
): Promise<Response> {
  const rateLimit = await runtime.rateLimit(tokenExchangeRateLimitKey(request));

  if (!rateLimit) {
    return oauthErrorResponse(429, "temporarily_unavailable");
  }

  if (request.headers.has("authorization")) {
    return oauthErrorResponse(401, "invalid_client", {
      "www-authenticate": wwwAuthenticateChallenge(request.headers.get("authorization")),
    });
  }

  if (!isFormUrlEncodedContentType(request.headers.get("content-type"))) {
    return oauthErrorResponse(400, "invalid_request");
  }

  const body = await readRequestBodyUpTo(request, maxTokenExchangeBodyBytes);

  if (!body.ok) {
    return oauthErrorResponse(body.status, "invalid_request");
  }

  const form = new URLSearchParams(new TextDecoder().decode(body.bytes));
  const grantType = singleFormValue(form, "grant_type");
  const requestedTokenType = singleFormValue(form, "requested_token_type");
  const subjectToken = singleFormValue(form, "subject_token");
  const subjectTokenType = singleFormValue(form, "subject_token_type");
  const tokenRequestOptions = parseInstallationAccessTokenRequestOptions(form);

  if (grantType === null) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (grantType !== tokenExchangeGrantType) {
    return oauthErrorResponse(400, "unsupported_grant_type");
  }

  if (subjectToken === null || subjectToken.length === 0 || subjectTokenType === null) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (subjectTokenType !== oidcIdTokenType) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (
    requestedTokenType !== accessTokenType &&
    requestedTokenType !== legacyGithubInstallationAccessTokenType
  ) {
    return oauthErrorResponse(400, "invalid_request");
  }

  if (!tokenRequestOptions.ok) {
    return oauthErrorResponse(400, tokenRequestOptions.error);
  }

  const tokenRequest = normalizeInstallationAccessTokenRequest(tokenRequestOptions.options);

  if (!tokenRequest.ok) {
    return oauthErrorResponse(400, tokenRequest.error);
  }

  const result = await runtime.exchange({
    request,
    subjectToken,
    tokenRequest: tokenRequest.tokenRequest,
  });

  if (!result.ok) {
    const failure = oauthErrorForTokenExchangeFailure(result);

    return oauthErrorResponse(failure.status, failure.error);
  }

  return oauthTokenResponse({
    access_token: result.token,
    expires_in: expiresInSeconds(result.expiresAt, runtime.now()),
    issued_token_type: requestedTokenType,
    scope: tokenRequest.tokenRequest.scope,
    token_type: "Bearer",
  });
}

function isFormUrlEncodedContentType(contentType: string | null): boolean {
  if (contentType === null) {
