export function createCyspbotWorker(): ExportedHandler<CyspbotEnv> {
  const app = new Hono<{ Bindings: CyspbotEnv }>();

  app.use(
    methodNotAllowed({
      app,
      onMethodNotAllowed: (_context, allowedMethods) =>
