import type { GitHubAppEnv } from "@github-app-token-broker/github/app";
import { normalizeInstallationAccessTokenRequest } from "@github-app-token-broker/github/installation-access-token-request";
import {
  type InstallationAccessTokenExchange,
  type InstallationAccessTokenExchangeResult,
} from "./installation-access-token-exchange.ts";

export interface GitHubAppInstallationTokenRpcInput {
  readonly subjectToken: string;
  readonly resource: string;
  readonly scope: string;
}

export type GitHubAppInstallationTokenRpcError =
  | "invalid_request"
  | "invalid_target"
  | "invalid_scope"
  | "server_error"
  | "temporarily_unavailable";

export type GitHubAppInstallationTokenRpcResult =
  | { readonly ok: true; readonly accessToken: string; readonly expiresAt: string }
  | { readonly ok: false; readonly error: GitHubAppInstallationTokenRpcError };

export interface GitHubAppInstallationTokenRpcDependencies {
  readonly exchange: InstallationAccessTokenExchange;
  readonly githubApp: GitHubAppEnv;
}

export function requestGithubAppInstallationToken(
  input: GitHubAppInstallationTokenRpcInput,
  dependencies: GitHubAppInstallationTokenRpcDependencies,
): Promise<GitHubAppInstallationTokenRpcResult>;
export async function requestGithubAppInstallationToken(
  input: unknown,
  dependencies: GitHubAppInstallationTokenRpcDependencies,
): Promise<GitHubAppInstallationTokenRpcResult> {
  const parsedInput = parseRpcInput(input);

  if (!parsedInput.ok) {
    return parsedInput;
  }

  const tokenRequest = normalizeInstallationAccessTokenRequest({
    resource: parsedInput.resource,
    scope: parsedInput.scope,
  });

  if (!tokenRequest.ok) {
    return {
      error: tokenRequest.error === "invalid_target" ? "invalid_target" : "invalid_scope",
      ok: false,
    };
  }

  let result: InstallationAccessTokenExchangeResult;

  try {
    result = await dependencies.exchange.exchange({
      githubApp: dependencies.githubApp,
      request: new Request("https://rpc.internal/token"),
      subjectToken: parsedInput.subjectToken,
      tokenRequest: tokenRequest.tokenRequest,
    });
  } catch {
    return { error: "server_error", ok: false };
  }

  return rpcResult(result);
}

function parseRpcInput(
  input: unknown,
):
  | ({ readonly ok: true } & GitHubAppInstallationTokenRpcInput)
  | { readonly ok: false; readonly error: "invalid_request" } {
  if (
    typeof input !== "object" ||
    input === null ||
    Array.isArray(input) ||
    ![Object.prototype, null].includes(Object.getPrototypeOf(input)) ||
    Object.getOwnPropertySymbols(input).length > 0
  ) {
    return { error: "invalid_request", ok: false };
  }

  const properties = Object.getOwnPropertyDescriptors(input);
  const keys = Object.keys(properties).sort();

  if (keys.join("\u0000") !== ["resource", "scope", "subjectToken"].join("\u0000")) {
    return { error: "invalid_request", ok: false };
  }

  const subjectToken = properties["subjectToken"]?.value;
  const resource = properties["resource"]?.value;
  const scope = properties["scope"]?.value;

  if (typeof subjectToken !== "string" || subjectToken.length === 0) {
    return { error: "invalid_request", ok: false };
  }

  if (typeof resource !== "string" || typeof scope !== "string") {
    return { error: "invalid_request", ok: false };
  }

  return { ok: true, resource, scope, subjectToken };
}

function rpcResult(
  result: InstallationAccessTokenExchangeResult,
): GitHubAppInstallationTokenRpcResult {
  if (result.ok) {
    return {
      accessToken: result.token,
      expiresAt: result.expiresAt,
      ok: true,
    };
  }

  if (result.stage === "authentication") {
    switch (result.reason) {
      case "invalid_token":
        return { error: "invalid_request", ok: false };
      case "oidc_internal_failure":
        return { error: "server_error", ok: false };
      case "oidc_provider_failure":
        return { error: "temporarily_unavailable", ok: false };
    }
  }

  switch (result.reason) {
    case "internal_failure":
      return { error: "server_error", ok: false };
    case "requested_permissions_unsupported":
      return { error: "invalid_scope", ok: false };
    case "subject_token_unacceptable":
      return { error: "invalid_request", ok: false };
    case "target_unsupported":
      return { error: "invalid_target", ok: false };
    case "upstream_failure":
      return { error: "server_error", ok: false };
    case "upstream_unavailable":
      return { error: "temporarily_unavailable", ok: false };
  }
