const tokenExchangeGrantType = "urn:ietf:params:oauth:grant-type:token-exchange";
const accessTokenType = "urn:ietf:params:oauth:token-type:access_token";
const oidcIdTokenType = "urn:ietf:params:oauth:token-type:id_token";

/** The logical audience shared by the workload issuer and token broker. */
export const githubAppTokenBrokerAudience = "https://cyspbot.chikachow.org";

/** The broker's OAuth 2.0 Token Exchange endpoint. */
export const githubAppTokenBrokerEndpoint = "https://cyspbot.chikachow.org/token";

export interface GitHubAppInstallationTokenRequest {
  readonly resource: string;
  readonly scope: string;
}

interface WorkloadIdentityToken {
  readonly token: string;
}

interface WorkloadIdentityIssuerBinding {
  issueToken(audience: string): Promise<WorkloadIdentityToken>;
}

interface GitHubAppTokenBrokerBinding {
  fetch(input: RequestInfo | URL, init?: RequestInit): Promise<Response>;
}

export interface GitHubAppTokenClientBindings {
  readonly WORKLOAD_IDENTITY_ISSUER: WorkloadIdentityIssuerBinding;
  readonly GITHUB_APP_TOKEN_BROKER: GitHubAppTokenBrokerBinding;
}

/**
 * Requests a GitHub App installation token through the broker's existing OAuth
 * Token Exchange endpoint. The returned Response preserves the broker's OAuth
 * success and error contract for the caller to consume.
 */
export async function requestGitHubAppInstallationToken(
  env: GitHubAppTokenClientBindings,
  request: GitHubAppInstallationTokenRequest,
): Promise<Response> {
  const resource = requireNonEmptyString(request.resource, "resource");
  const scope = requireNonEmptyString(request.scope, "scope");
  const issuedToken = await env.WORKLOAD_IDENTITY_ISSUER.issueToken(githubAppTokenBrokerAudience);
  const subjectToken = requireIssuedToken(issuedToken);

  const body = new URLSearchParams({
    grant_type: tokenExchangeGrantType,
    requested_token_type: accessTokenType,
    resource,
    scope,
    subject_token: subjectToken,
    subject_token_type: oidcIdTokenType,
  });

  return env.GITHUB_APP_TOKEN_BROKER.fetch(githubAppTokenBrokerEndpoint, {
    body,
    headers: {
      accept: "application/json",
      "content-type": "application/x-www-form-urlencoded",
    },
    method: "POST",
  });
}

function requireIssuedToken(value: unknown): string {
  if (
    typeof value !== "object" ||
    value === null ||
    typeof (value as { token?: unknown }).token !== "string" ||
    (value as { token: string }).token.length === 0
  ) {
    throw new TypeError("WORKLOAD_IDENTITY_ISSUER returned an invalid token.");
  }

  return (value as { token: string }).token;
}

function requireNonEmptyString(value: string, name: string): string {
  if (typeof value !== "string" || value.trim().length === 0) {
    throw new TypeError(`${name} must be a non-empty string.`);
  }

  return value;
}
import {
  githubAppTokenBrokerAudience,
  githubAppTokenBrokerEndpoint,
  requestGitHubAppInstallationToken,
  type GitHubAppTokenClientBindings,
} from "@cyspbot/cyspbot/github-app-token";
import { describe, expect, it } from "vitest";

describe("requestGitHubAppInstallationToken", () => {
  it("gets a workload identity token and sends an OAuth token exchange", async () => {
    const audiences: string[] = [];
    const requests: Array<{ input: RequestInfo | URL; init: RequestInit | undefined }> = [];
    const brokerResponse = new Response(
      JSON.stringify({
        access_token: "ghs_test_token",
        expires_in: 300,
        issued_token_type: "urn:ietf:params:oauth:token-type:access_token",
        scope: "contents:read",
        token_type: "Bearer",
      }),
      { headers: { "content-type": "application/json" }, status: 200 },
    );
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch(input, init) {
          requests.push({ init, input });
          return Promise.resolve(brokerResponse);
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken(audience: string) {
          audiences.push(audience);
          return Promise.resolve({ token: "eyJ.test.workload.identity" });
        },
      },
    };

    const response = await requestGitHubAppInstallationToken(env, {
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
    });

    expect(response).toBe(brokerResponse);
    expect(audiences).toEqual([githubAppTokenBrokerAudience]);
    expect(requests).toHaveLength(1);
    expect(requests[0]?.input).toBe(githubAppTokenBrokerEndpoint);
    expect(requests[0]?.init?.method).toBe("POST");
    expect(new Headers(requests[0]?.init?.headers).get("accept")).toBe("application/json");
    expect(new Headers(requests[0]?.init?.headers).get("content-type")).toBe(
      "application/x-www-form-urlencoded",
    );

    const requestBody = requests[0]?.init?.body;
    if (!(requestBody instanceof URLSearchParams)) {
      throw new TypeError("expected a URLSearchParams token-exchange body");
    }

    expect(Object.fromEntries(requestBody)).toEqual({
      grant_type: "urn:ietf:params:oauth:grant-type:token-exchange",
      requested_token_type: "urn:ietf:params:oauth:token-type:access_token",
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
      subject_token: "eyJ.test.workload.identity",
      subject_token_type: "urn:ietf:params:oauth:token-type:id_token",
    });
  });

  it("does not contact the broker when the request is empty", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken() {
          issuerCalls += 1;
          return Promise.resolve({ token: "unused" });
        },
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "",
        scope: "contents:read",
      }),
    ).rejects.toThrow("resource must be a non-empty string");
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("does not contact the broker when the issuer returns no token", async () => {
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken: async () => ({ token: "" }),
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "https://api.github.com/repos/chikachow/cyspbot",
        scope: "contents:read",
      }),
    ).rejects.toThrow("WORKLOAD_IDENTITY_ISSUER returned an invalid token");
    expect(brokerCalls).toBe(0);
  });

  it("requires a non-empty scope before contacting either binding", async () => {
    let issuerCalls = 0;
    let brokerCalls = 0;
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          brokerCalls += 1;
          return Promise.reject(new Error("broker should not be contacted"));
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken() {
          issuerCalls += 1;
          return Promise.resolve({ token: "unused" });
        },
      },
    };

    await expect(
      requestGitHubAppInstallationToken(env, {
        resource: "https://api.github.com/repos/chikachow/cyspbot",
        scope: " ",
      }),
    ).rejects.toThrow("scope must be a non-empty string");
    expect(issuerCalls).toBe(0);
    expect(brokerCalls).toBe(0);
  });

  it("returns broker errors unchanged for the caller to interpret", async () => {
    const brokerResponse = new Response(JSON.stringify({ error: "invalid_scope" }), {
      headers: { "content-type": "application/json" },
      status: 400,
    });
    const env: GitHubAppTokenClientBindings = {
      GITHUB_APP_TOKEN_BROKER: {
        fetch() {
          return Promise.resolve(brokerResponse);
        },
      },
      WORKLOAD_IDENTITY_ISSUER: {
        issueToken: async () => ({ token: "eyJ.test.workload.identity" }),
      },
    };

    const response = await requestGitHubAppInstallationToken(env, {
      resource: "https://api.github.com/repos/chikachow/cyspbot",
      scope: "contents:read",
    });

    expect(response).toBe(brokerResponse);
    expect(response.status).toBe(400);
    await expect(response.json()).resolves.toEqual({ error: "invalid_scope" });
  });
});

